head.script:
// 화면 리사이징

scwin.gIsurCd = frame.opener.p_isur_cd; // 회사코드
scwin.gChrgNm = frame.opener.p_chrg_nm;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30642.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_MASTER_OnFail
 * @description MASTER On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MASTER_OnFail = async function() {
    try {
        await $c.win.alert(dts_MASTER);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30642.dts_MASTER_OnFail" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnLoadError
 * @description dts_MASTER 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_MASTER);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30642.dts_MASTER_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnLoadCompleted
 * @description dts_MASTER 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_MASTER.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30642.dts_MASTER_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF30642.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "공시교육참가현황", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30642.btn_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 담당자명
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&ISUR_CD=" + scwin.gIsurCd;
    url += "&EDU_KIND_CD=";
    url += "&YYYY=";
    url += "&CHRG_NM=" + scwin.gChrgNm;
    url += "&DEP_CD=";
    url += "&EMP_NO=";
    url += "&SCREN_ID=" + "ULDSTF30642.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
